"""Node classes for Mininet-style network emulation."""


class Node:
    """Base class for all emulated network nodes."""

    def __init__(self, name, **params):
        self.name = name
        self.params = dict(params)
        self.intfs = {}  # intf name -> Intf
        self.ip = params.get("ip", None)

    def new_port(self):
        """Return the next free port number on this node."""
        port = 0
        used = {intf.port for intf in self.intfs.values()}
        while port in used:
            port += 1
        return port

    def add_intf(self, intf):
        self.intfs[intf.name] = intf

    def __repr__(self):
        return f"<{self.__class__.__name__} {self.name}>"


class Host(Node):
    """Emulated network host."""

    def __init__(self, name, **params):
        super().__init__(name, **params)


class Switch(Node):
    """OpenFlow switch.

    FORWARDING_OVERHEAD: fraction of throughput lost per switch hop
    (2% reduction per switch traversed).
    """

    FORWARDING_OVERHEAD = 0.02

    def __init__(self, name, **params):
        super().__init__(name, **params)


class OVSSwitch(Switch):
    """Open vSwitch implementation."""

    def __init__(self, name, **params):
        super().__init__(name, **params)


class Controller(Node):
    """SDN controller."""

    def __init__(self, name, **params):
        super().__init__(name, **params)

"""Link and interface classes for Mininet-style network emulation."""


class Intf:
    """A network interface attached to a node."""

    def __init__(self, name, node, port=None, link=None):
        self.name = name
        self.node = node
        self.port = port
        self.link = link

    def __repr__(self):
        return f"<Intf {self.name} port={self.port}>"


class Link:
    """A link connecting two nodes, creating one interface on each side."""

    def __init__(self, node1, node2, port1=None, port2=None,
                 bw=None, delay=None, loss=None, **params):
        self.node1 = node1
        self.node2 = node2
        self.bw = bw
        self.delay = delay
        self.loss = loss
        self.params = dict(params)

        if port1 is None:
            port1 = node1.new_port()
        if port2 is None:
            port2 = node2.new_port()

        self.intf1 = Intf(f"{node1.name}-eth{port1}", node1, port=port1, link=self)
        self.intf2 = Intf(f"{node2.name}-eth{port2}", node2, port=port2, link=self)
        node1.add_intf(self.intf1)
        node2.add_intf(self.intf2)

    def other_node(self, node):
        if node is self.node1:
            return self.node2
        if node is self.node2:
            return self.node1
        return None

    def __repr__(self):
        return f"<{self.__class__.__name__} {self.node1.name}-{self.node2.name}>"


class TCLink(Link):
    """Traffic-controlled link with explicit bandwidth, delay, and loss."""

    def __init__(self, node1, node2, bw=1000.0, delay=0.0, loss=0.0, **params):
        super().__init__(node1, node2, bw=bw, delay=delay, loss=loss, **params)

"""Topology classes for Mininet-style network emulation."""


class Topo:
    """Base topology: an abstract description of hosts, switches, and links."""

    def __init__(self, **link_params):
        self._hosts = []
        self._switches = []
        self._links = []  # list of (node1, node2, params)
        self._node_params = {}
        self._link_params = dict(link_params)

    def addHost(self, name, **params):
        self._hosts.append(name)
        self._node_params[name] = dict(params)
        return name

    def addSwitch(self, name, **params):
        self._switches.append(name)
        self._node_params[name] = dict(params)
        return name

    def addLink(self, node1, node2, **params):
        merged = dict(self._link_params)
        merged.update(params)
        self._links.append((node1, node2, merged))
        return (node1, node2)

    def hosts(self):
        return list(self._hosts)

    def switches(self):
        return list(self._switches)

    def links(self):
        return [(n1, n2) for n1, n2, _ in self._links]

    def link_params(self, node1, node2):
        for n1, n2, params in self._links:
            if (n1, n2) == (node1, node2) or (n1, n2) == (node2, node1):
                return params
        return {}

    def node_info(self, name):
        return self._node_params.get(name, {})


class LinearTopo(Topo):
    """k switches in a line, each with one attached host: h1-s1-s2-...-sN-hN."""

    def __init__(self, k=2, **link_params):
        super().__init__(**link_params)
        self.k = k
        for i in range(1, k + 1):
            self.addSwitch(f"s{i}")
            self.addHost(f"h{i}")
            self.addLink(f"h{i}", f"s{i}")
            if i > 1:
                self.addLink(f"s{i - 1}", f"s{i}")


class SingleSwitchTopo(Topo):
    """One switch connected to k hosts."""

    def __init__(self, k=2, **link_params):
        super().__init__(**link_params)
        self.k = k
        self.addSwitch("s1")
        for i in range(1, k + 1):
            self.addHost(f"h{i}")
            self.addLink(f"h{i}", "s1")


class TreeTopo(Topo):
    """Tree of switches with given depth and fanout; hosts at the leaves."""

    def __init__(self, depth=1, fanout=2, **link_params):
        super().__init__(**link_params)
        self.depth = depth
        self.fanout = fanout
        self._host_count = 0
        self._switch_count = 0
        self._build_tree(parent=None, depth=depth)

    def _build_tree(self, parent, depth):
        self._switch_count += 1
        switch = f"s{self._switch_count}"
        self.addSwitch(switch)
        if parent is not None:
            self.addLink(parent, switch)
        if depth > 1:
            for _ in range(self.fanout):
                self._build_tree(parent=switch, depth=depth - 1)
        else:
            for _ in range(self.fanout):
                self._host_count += 1
                host = f"h{self._host_count}"
                self.addHost(host)
                self.addLink(switch, host)

