"""Service Function Chain modeling for Containernet."""


class VNF:
    """A virtual network function with processing delay and overhead."""

    def __init__(self, name, processing_delay_ms=1.0, overhead_pct=5.0):
        self.name = name
        self.processing_delay_ms = processing_delay_ms
        self.overhead_pct = overhead_pct

    @property
    def throughput_factor(self):
        """Fraction of link bandwidth preserved after this VNF."""
        return 1.0 - self.overhead_pct / 100.0

    def __repr__(self):
        return f"<VNF {self.name}>"


class ServiceFunctionChain:
    """An ordered chain of VNFs with uniform link parameters.

    num_links includes the client->first-VNF and last-VNF->server links.
    """

    def __init__(self, vnfs=None, link_bw=1000.0, link_delay=0.5):
        self.vnfs = list(vnfs) if vnfs else []
        self.link_bw = link_bw
        self.link_delay = link_delay

    def add_vnf(self, vnf):
        self.vnfs.append(vnf)
        return vnf

    @property
    def num_links(self):
        return len(self.vnfs) + 1

    def compute_throughput(self):
        """Chain throughput: link bandwidth times all VNF factors."""
        throughput = self.link_bw
        for vnf in self.vnfs:
            throughput *= vnf.throughput_factor
        return throughput

    def compute_latency(self):
        """End-to-end latency: per-link delays plus VNF processing."""
        latency = self.num_links * self.link_delay
        latency += sum(vnf.processing_delay_ms for vnf in self.vnfs)
        return latency

"""Containernet: Mininet extended with Docker container hosts."""

from .container import DockerHost
from .net import Mininet
from .utils import jains_fairness_index


class Containernet(Mininet):
    """Network with mixed regular hosts and container-backed hosts."""

    def __init__(self, *args, **kwargs):
        self.docker_hosts = []
        super().__init__(*args, **kwargs)

    def addDocker(self, name, image="ubuntu:latest", cls=DockerHost, **params):
        """Add a container-backed host to the network."""
        docker = self.addHost(name, cls=cls, image=image, **params)
        self.docker_hosts.append(docker)
        return docker

    def compute_resource_fairness(self):
        """Jain's fairness index over container CPU share allocations."""
        shares = [d.cpu_shares for d in self.docker_hosts]
        return jains_fairness_index(shares)

    def total_nodes(self):
        """Total number of hosts and switches in the network."""
        return len(self.hosts) + len(self.switches)

    def startup_overhead_ratio(self):
        """Ratio of container startup time to regular host startup time."""
        return DockerHost.STARTUP_OVERHEAD_MS / DockerHost.HOST_STARTUP_MS

"""P4-programmable data plane simulation on top of Mininet switches."""

from .node import Switch
from .topo import Topo


class P4MatchActionTable:
    """A named match-action table with configurable match fields."""

    def __init__(self, name, match_fields, max_size=1024):
        self.name = name
        self.match_fields = list(match_fields)
        self.max_size = max_size
        self.rules = []

    def add_rule(self, match_dict, action_name, action_params=None, priority=0):
        """Add a rule; returns False when the table is full."""
        if len(self.rules) >= self.max_size:
            return False
        self.rules.append({
            "match": dict(match_dict),
            "action_name": action_name,
            "action_params": dict(action_params) if action_params else {},
            "priority": priority,
        })
        return True

    def _rule_matches(self, rule, packet_headers):
        return all(packet_headers.get(field) == value
                   for field, value in rule["match"].items())

    def lookup(self, packet_headers):
        """Return the highest-priority matching rule, or None."""
        best = None
        for rule in self.rules:
            if not self._rule_matches(rule, packet_headers):
                continue
            if best is None or rule["priority"] > best["priority"]:
                best = rule
        return best

    def delete_rule(self, match_dict):
        """Remove the rule with exactly these match fields."""
        for i, rule in enumerate(self.rules):
            if rule["match"] == dict(match_dict):
                return self.rules.pop(i)
        return None

    def size(self):
        return len(self.rules)

    def clear(self):
        self.rules = []


class P4Parser:
    """Extracts header fields from raw packet bytes.

    header_defs maps field_name -> (byte_offset, byte_length).
    """

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs)

    @property
    def header_length(self):
        if not self.header_defs:
            return 0
        return max(offset + length
                   for offset, length in self.header_defs.values())

    def parse(self, packet_data):
        """Return a dict of extracted header field values."""
        headers = {}
        for field, (offset, length) in self.header_defs.items():
            chunk = bytes(packet_data[offset:offset + length])
            headers[field] = int.from_bytes(chunk, "big")
        return headers

    def is_valid(self, packet_data):
        """Check the packet has at least the minimum required length."""
        return len(packet_data) >= self.header_length


class P4Deparser:
    """Reassembles packet bytes from (possibly modified) header fields."""

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs)

    @property
    def header_length(self):
        if not self.header_defs:
            return 0
        return max(offset + length
                   for offset, length in self.header_defs.values())

    def deparse(self, headers, payload):
        """Rebuild packet bytes from header fields plus payload."""
        buf = bytearray(self.header_length)
        for field, (offset, length) in self.header_defs.items():
            value = int(headers.get(field, 0))
            buf[offset:offset + length] = value.to_bytes(length, "big")
        return bytes(buf) + bytes(payload)


class P4Counter:
    """Per-flow packet and byte counter array."""

    def __init__(self, name, size):
        self.name = name
        self.size = size
        self._packets = [0] * size
        self._bytes = [0] * size

    def increment(self, index, packet_bytes):
        self._packets[index] += 1
        self._bytes[index] += packet_bytes

    def read(self, index):
        """Return the (packets, bytes) tuple for one counter cell."""
        return (self._packets[index], self._bytes[index])

    def reset(self, index=None):
        """Reset one counter cell, or all cells when index is None."""
        if index is None:
            self._packets = [0] * self.size
            self._bytes = [0] * self.size
        else:
            self._packets[index] = 0
            self._bytes[index] = 0

    def total_packets(self):
        return sum(self._packets)

    def total_bytes(self):
        return sum(self._bytes)


class P4Switch(Switch):
    """A switch with a programmable P4 pipeline."""

    def __init__(self, name, program=None, **params):
        super().__init__(name, **params)
        self.program = program
        self.tables = {}
        self.counters = {}
        self.parser = None
        self.deparser = None
        self.multicast_groups = {}

    def add_table(self, table):
        self.tables[table.name] = table
        return table

    def add_counter(self, counter):
        self.counters[counter.name] = counter
        return counter

    def set_parser(self, parser):
        self.parser = parser

    def set_deparser(self, deparser):
        self.deparser = deparser

    def get_table(self, name):
        return self.tables.get(name)

    def get_counter(self, name):
        return self.counters.get(name)

    @property
    def pipeline_latency_us(self):
        """Pipeline processing latency: 0.5us per table."""
        return 0.5 * len(self.tables)

    def process_packet(self, packet_data):
        """Run the full pipeline: parse -> match-action tables -> deparse.

        Returns the deparsed packet bytes, or None when a matched rule
        drops the packet.
        """
        if self.parser is not None:
            if not self.parser.is_valid(packet_data):
                return None
            headers = self.parser.parse(packet_data)
            payload = packet_data[self.parser.header_length:]
        else:
            headers = {}
            payload = packet_data

        for table in self.tables.values():
            rule = table.lookup(headers)
            if rule is None:
                continue
            if rule["action_name"] == "drop":
                return None
            for field, value in rule["action_params"].items():
                headers[field] = value

        if self.deparser is not None:
            return self.deparser.deparse(headers, payload)
        return payload


class P4Topology(Topo):
    """A linear chain of P4 switches, each with connected hosts."""

    def __init__(self, num_switches=4, num_hosts_per_switch=2, **link_params):
        super().__init__(**link_params)
        self.num_switches = num_switches
        self.num_hosts_per_switch = num_hosts_per_switch
        self.p4_switches = []
        host_count = 0
        prev_switch = None
        for i in range(1, num_switches + 1):
            switch = self.addP4Switch(f"s{i}")
            if prev_switch is not None:
                self.addLink(prev_switch, switch)
            prev_switch = switch
            for _ in range(num_hosts_per_switch):
                host_count += 1
                host = f"h{host_count}"
                self.addHost(host)
                self.addLink(host, switch)

    def addP4Switch(self, name, **params):
        """Add a switch and record it as P4-capable."""
        params.setdefault("p4", True)
        self.addSwitch(name, **params)
        self.p4_switches.append(name)
        return name


class P4MulticastGroup:
    """Manages multicast packet replication to a set of output ports."""

    def __init__(self, group_id, ports):
        self.group_id = group_id
        self.ports = list(ports)

    def replicate(self, packet_data):
        """Return a (port, packet_data) tuple for each output port."""
        return [(port, packet_data) for port in self.ports]

    def add_port(self, port):
        if port not in self.ports:
            self.ports.append(port)

    def remove_port(self, port):
        if port in self.ports:
            self.ports.remove(port)

"""SDN controller with flow rule management, Dijkstra paths, and recovery."""

import heapq


class FlowRule:
    """An OpenFlow-style flow entry."""

    def __init__(self, match_fields, actions, priority=100,
                 idle_timeout=0, hard_timeout=0):
        self.match_fields = dict(match_fields)
        self.actions = list(actions)
        self.priority = priority
        self.idle_timeout = idle_timeout
        self.hard_timeout = hard_timeout
        self.packet_count = 0
        self.byte_count = 0
        self.install_time = 0.0

    def matches(self, packet_headers):
        """Check whether a packet's headers match this rule."""
        return all(packet_headers.get(field) == value
                   for field, value in self.match_fields.items())

    def is_expired(self, current_time, last_matched_time):
        """Check idle/hard timeout expiry at the given time."""
        if self.hard_timeout > 0:
            if current_time - self.install_time >= self.hard_timeout:
                return True
        if self.idle_timeout > 0 and last_matched_time is not None:
            if current_time - last_matched_time >= self.idle_timeout:
                return True
        return False


class FlowTable:
    """Per-switch flow table with capacity and timeout eviction."""

    def __init__(self, switch_name, capacity=4096):
        self.switch_name = switch_name
        self.capacity = capacity
        self.rules = []

    def install(self, rule):
        """Add a FlowRule; returns False when the table is at capacity."""
        if len(self.rules) >= self.capacity:
            return False
        self.rules.append(rule)
        return True

    def remove(self, match_fields):
        """Remove the rule with exactly these match fields."""
        for i, rule in enumerate(self.rules):
            if rule.match_fields == dict(match_fields):
                return self.rules.pop(i)
        return None

    def lookup(self, packet_headers):
        """Find the highest-priority rule matching the packet."""
        best = None
        for rule in self.rules:
            if not rule.matches(packet_headers):
                continue
            if best is None or rule.priority > best.priority:
                best = rule
        return best

    def evict_expired(self, current_time, last_matched_times=None):
        """Remove expired rules; returns the number evicted.

        last_matched_times maps id(rule) -> last matched timestamp.
        """
        last_matched_times = last_matched_times or {}
        evicted = 0
        kept = []
        for rule in self.rules:
            last = last_matched_times.get(id(rule))
            if rule.is_expired(current_time, last):
                evicted += 1
            else:
                kept.append(rule)
        self.rules = kept
        return evicted

    def size(self):
        return len(self.rules)

    def stats(self):
        """List of (rule, packet_count, byte_count) tuples."""
        return [(rule, rule.packet_count, rule.byte_count)
                for rule in self.rules]

    def clear(self):
        self.rules = []

    def utilization(self):
        """Fraction of table capacity in use."""
        return len(self.rules) / self.capacity


class SDNController:
    """Base SDN controller: topology graph, flow tables, path computation."""

    def __init__(self, name):
        self.name = name
        self.adj = {}  # node -> {neighbor: weight}
        self.flow_tables = {}
        self.hosts = {}  # host name -> ip
        self._installed_flows = []  # (src, dst, src_ip, dst_ip, priority, path)

    def add_switch(self, switch_name):
        """Register a switch and create its flow table."""
        self.adj.setdefault(switch_name, {})
        self.flow_tables[switch_name] = FlowTable(switch_name)

    def add_host(self, host_name, ip=None):
        self.adj.setdefault(host_name, {})
        self.hosts[host_name] = ip

    def add_link(self, node1, node2, weight=1):
        """Add a weighted link to the topology graph."""
        self.adj.setdefault(node1, {})[node2] = weight
        self.adj.setdefault(node2, {})[node1] = weight

    def remove_link(self, node1, node2):
        """Remove a link (simulates a link failure)."""
        self.adj.get(node1, {}).pop(node2, None)
        self.adj.get(node2, {}).pop(node1, None)

    def topology_discovery(self, net):
        """Build the topology graph from a Mininet network instance."""
        for switch in net.switches:
            self.add_switch(switch.name)
        for host in net.hosts:
            self.add_host(host.name, host.ip)
        for link in net.links:
            self.add_link(link.node1.name, link.node2.name, weight=1)

    def compute_path(self, src, dst):
        """Dijkstra shortest path; returns a list of node names.

        Returns an empty list when src and dst are disconnected.
        """
        if src == dst:
            return [src] if src in self.adj else []
        if src not in self.adj or dst not in self.adj:
            return []
        dist = {src: 0}
        prev = {src: None}
        pq = [(0, src)]
        visited = set()
        while pq:
            d, u = heapq.heappop(pq)
            if u in visited:
                continue
            visited.add(u)
            if u == dst:
                break
            for v, w in self.adj.get(u, {}).items():
                if v in visited:
                    continue
                nd = d + w
                if v not in dist or nd < dist[v]:
                    dist[v] = nd
                    prev[v] = u
                    heapq.heappush(pq, (nd, v))
        if dst not in prev:
            return []
        path = []
        cur = dst
        while cur is not None:
            path.append(cur)
            cur = prev[cur]
        path.reverse()
        return path

    def compute_all_paths(self):
        """Compute shortest paths between all host pairs."""
        paths = {}
        host_names = list(self.hosts)
        for src in host_names:
            for dst in host_names:
                if src != dst:
                    paths[(src, dst)] = self.compute_path(src, dst)
        return paths

    def install_path_rules(self, path, src_ip, dst_ip, priority=100):
        """Install a forwarding rule on each switch along the path."""
        installed = 0
        switches = [node for node in path if node in self.flow_tables]
        for i, switch_name in enumerate(switches):
            out_port = i + 1
            rule = FlowRule(
                match_fields={"src_ip": src_ip, "dst_ip": dst_ip},
                actions=[{"type": "output", "port": out_port}],
                priority=priority)
            if self.flow_tables[switch_name].install(rule):
                installed += 1
        if installed and path:
            src, dst = path[0], path[-1]
            self._installed_flows.append((src, dst, src_ip, dst_ip,
                                          priority, list(path)))
        return installed

    def total_rules_installed(self):
        """Sum of rules across all switch flow tables."""
        return sum(table.size() for table in self.flow_tables.values())

    def handle_link_failure(self, node1, node2):
        """Remove a failed link and reinstall rules on recomputed paths.

        Returns the number of rules reinstalled.
        """
        self.remove_link(node1, node2)
        reinstalled = 0
        remaining_flows = []
        for src, dst, src_ip, dst_ip, priority, old_path in self._installed_flows:
            affected = any(
                (u, v) == (node1, node2) or (u, v) == (node2, node1)
                for u, v in zip(old_path, old_path[1:]))
            if not affected:
                remaining_flows.append((src, dst, src_ip, dst_ip,
                                        priority, old_path))
                continue
            # Clear stale rules for this flow, then install on the new path.
            for table in self.flow_tables.values():
                table.remove({"src_ip": src_ip, "dst_ip": dst_ip})
            new_path = self.compute_path(src, dst)
            if new_path:
                switches = [n for n in new_path if n in self.flow_tables]
                for i, switch_name in enumerate(switches):
                    rule = FlowRule(
                        match_fields={"src_ip": src_ip, "dst_ip": dst_ip},
                        actions=[{"type": "output", "port": i + 1}],
                        priority=priority)
                    if self.flow_tables[switch_name].install(rule):
                        reinstalled += 1
                remaining_flows.append((src, dst, src_ip, dst_ip,
                                        priority, new_path))
        self._installed_flows = remaining_flows
        return reinstalled


class ReactiveController(SDNController):
    """Installs rules on demand in response to packet-in events."""

    def __init__(self, name):
        super().__init__(name)
        self.packet_in_count = 0

    def handle_packet_in(self, switch_name, packet_headers):
        """On a table miss, compute a path and install rules along it."""
        self.packet_in_count += 1
        src_ip = packet_headers.get("src_ip")
        dst_ip = packet_headers.get("dst_ip")
        ip_to_host = {ip: name for name, ip in self.hosts.items()}
        src = ip_to_host.get(src_ip, src_ip)
        dst = ip_to_host.get(dst_ip, dst_ip)
        path = self.compute_path(src, dst)
        if path:
            self.install_path_rules(path, src_ip, dst_ip)
        return path


class ProactiveController(SDNController):
    """Pre-installs forwarding rules for all host pairs."""

    rule_install_time_ms = 0.1

    def install_all_rules(self, hosts_with_ips):
        """Install rules for every src-dst pair along their paths.

        hosts_with_ips is a list of (host_name, ip) tuples.
        Returns the total number of rules installed.
        """
        total = 0
        for src_name, src_ip in hosts_with_ips:
            for dst_name, dst_ip in hosts_with_ips:
                if src_name == dst_name:
                    continue
                path = self.compute_path(src_name, dst_name)
                if path:
                    total += self.install_path_rules(path, src_ip, dst_ip)
        return total

    def total_install_time(self):
        """Total simulated time (ms) to install all current rules."""
        return self.total_rules_installed() * self.rule_install_time_ms
